package access

import (
	"context"
	"maps"
	"slices"
	"testing"
)

// viewerEqual reports whether a and b carry the same authority scope,
// field by field (Viewer holds slices and maps, so it is not
// struct-comparable; field-level assertions also name the drifted field).
func viewerEqual(a, b Viewer) bool {
	return a.Admin == b.Admin &&
		a.UserID == b.UserID &&
		slices.Equal(a.VisibleLibraryIDs, b.VisibleLibraryIDs) &&
		maps.Equal(a.ChainMutes, b.ChainMutes)
}

// assertZeroViewer fails the test if v carries ANY authority — the zero
// Viewer hides everything (fail closed).
func assertZeroViewer(t *testing.T, v Viewer) {
	t.Helper()
	if v.Admin {
		t.Fatal("Admin = true, want false (zero Viewer fails closed)")
	}
	if v.UserID != 0 {
		t.Fatalf("UserID = %d, want 0", v.UserID)
	}
	if len(v.VisibleLibraryIDs) != 0 {
		t.Fatalf("VisibleLibraryIDs = %v, want empty", v.VisibleLibraryIDs)
	}
	if len(v.ChainMutes) != 0 {
		t.Fatalf("ChainMutes = %v, want empty", v.ChainMutes)
	}
}

// TestViewerContextRoundtrip pins the carrier's stash-and-read contract: a
// viewer placed via WithViewer reads back from FromContext with every field
// intact — including through a context DERIVED from the stashed one (the
// request-middleware pattern, where reader and stasher hold different ctx
// values on the same chain).
func TestViewerContextRoundtrip(t *testing.T) {
	ids := []int64{2, 5, 9}
	mutes := map[string]bool{"tmdb": true}
	want := User(42, ids, mutes)

	t.Run("SameContext", func(t *testing.T) {
		ctx := WithViewer(context.Background(), want)
		got := FromContext(ctx)
		if !viewerEqual(got, want) {
			t.Fatalf("FromContext(WithViewer(ctx, v)) = %+v, want %+v", got, want)
		}
	})

	t.Run("DerivedContext", func(t *testing.T) {
		// A child of the stashed context (timeout, request-scoped cancel)
		// still carries the viewer — the seam is chain-wide by context law.
		ctx := WithViewer(context.Background(), want)
		derived, cancel := context.WithTimeout(ctx, 1_000_000_000)
		defer cancel()
		got := FromContext(derived)
		if !viewerEqual(got, want) {
			t.Fatalf("FromContext(derived ctx) = %+v, want %+v", got, want)
		}
	})

	t.Run("Overwrite", func(t *testing.T) {
		// A later WithViewer on the same chain wins — the latest stash is
		// what reads back (one key, one seam; no accumulation).
		other := Admin()
		ctx := WithViewer(WithViewer(context.Background(), want), other)
		got := FromContext(ctx)
		if !viewerEqual(got, other) {
			t.Fatalf("FromContext(double stash) = %+v, want the last-stashed %+v", got, other)
		}
	})
}

// TestViewerContextAbsentIsZero pins the fail-closed floor: a context with NO
// stashed viewer reads back the zero Viewer — no Admin flag, no user id, no
// visible set, no mutes — so an unstashed read can never widen authority.
func TestViewerContextAbsentIsZero(t *testing.T) {
	t.Run("BareContext", func(t *testing.T) {
		assertZeroViewer(t, FromContext(context.Background()))
	})

	t.Run("NilContext", func(t *testing.T) {
		// The read is nil-safe: a nil context reads as absence, never panics.
		assertZeroViewer(t, FromContext(nil))
	})

	t.Run("ForeignValue", func(t *testing.T) {
		// A foreign context — values stashed by other packages — carries no
		// viewer; a non-Viewer under any key is indistinguishable from
		// absence and must read as the zero value, never panic.
		ctx := context.WithValue(context.Background(), "unrelated", "value")
		assertZeroViewer(t, FromContext(ctx))
	})
}
